package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="push_tickets")public class PushTicketEntity{@Id public UUID id;@Column(name="delivery_id",nullable=false,unique=true)public UUID deliveryId;@Column(name="device_token_id",nullable=false)public UUID deviceTokenId;@Column(name="expo_ticket_id",unique=true,length=100)public String expoTicketId;@Column(nullable=false,length=30)public String status;@Column(name="error_code",length=100)public String errorCode;@Column(name="error_message",length=500)public String errorMessage;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="receipt_checked_at")public Instant receiptCheckedAt;}
